fn classify_provider_error(msg: &str) -> Option<&'static str> {
    let lower = msg.to_lowercase();
    // Anthropic / OpenAI: "credit balance is too low" / "you exceeded your current quota"
    if lower.contains("credit balance") && lower.contains("too low") {
        return Some("credit_balance_too_low");
    }
    if lower.contains("insufficient_quota") || lower.contains("exceeded your current quota") {
        return Some("quota_exceeded");
    }
    // Generico billing / pagamento
    if lower.contains("plans & billing") || lower.contains("upgrade or purchase credits")
        || lower.contains("billing required") || lower.contains("payment required")
    {
        return Some("billing_required");
    }
    None
}

