/// Schema del tool `dispatch_subagents` (batch parallelo, Comp.0/3b).
/// Stesso gating di `dispatch_subagent`: esposto solo se subagents_enabled
/// e con almeno un kind in whitelist. E' la base del DAG scheduler parallelo.
async fn build_dispatch_subagents_schema(state: &AgentState) -> Option<serde_json::Value> {
    let enabled = read_setting_bool("orchestrator.subagents_enabled").await.unwrap_or(false);
    if !enabled {
        return None;
    }
    let kinds = read_subagent_kinds().await;
    if kinds.is_empty() {
        return None;
    }
    let kinds_desc = kinds.join(", ");
    let desc = format!(
        "Delega PIU' task a sub-agent specializzati eseguiti IN PARALLELO (a ondate). \
         Kind disponibili: {kinds_desc}. Usalo quando hai piu' lavori INDIPENDENTI da svolgere \
         contemporaneamente (es. rami indipendenti di un piano/DAG). Per un singolo task usa dispatch_subagent."
    );
    Some(serde_json::json!({
        "name": "dispatch_subagents",
        "description": desc,
        "input_schema": {
            "type": "object",
            "properties": {
                "tasks": {
                    "type": "array",
                    "description": "Task indipendenti (1-8) da eseguire in parallelo",
                    "items": {
                        "type": "object",
                        "properties": {
                            "kind": {"type": "string", "enum": kinds, "description": "Tipo di sub-agent"},
                            "task": {"type": "string", "description": "Descrizione completa del task"},
                            "context": {"type": "string", "description": "Contesto rilevante (opzionale)"},
                            "expected_output_format": {"type": "string", "description": "Formato atteso (opzionale)"}
                        },
                        "required": ["kind", "task"]
                    }
                },
                "max_parallel": {"type": "integer", "description": "Ampiezza ondata concorrente (default 2, max 4)"}
            },
            "required": ["tasks"]
        }
    }))
}

