/// Legge il CORE di tool da `settings.agent.tools.core_whitelist` (CSV).
/// Ritorna sempre una lista non vuota: in caso di DB down o chiave assente,
/// usa il fallback hardcoded `CORE_TOOLS_FALLBACK`.
async fn load_core_tools(db: &PgPool) -> Vec<String> {
    let csv: Option<String> = sqlx::query_scalar(
        "SELECT value FROM settings WHERE key = 'agent.tools.core_whitelist'",
    )
    .fetch_optional(db)
    .await
    .ok()
    .flatten();
    match csv {
        Some(s) if !s.trim().is_empty() => s
            .split(',')
            .map(|t| t.trim().to_string())
            .filter(|t| !t.is_empty())
            .collect(),
        _ => {
            tracing::warn!(
                "load_core_tools: settings.agent.tools.core_whitelist assente, uso fallback ({} tool)",
                CORE_TOOLS_FALLBACK.len(),
            );
            CORE_TOOLS_FALLBACK
                .iter()
                .map(|s| s.to_string())
                .collect()
        }
    }
}

/// Legge il flag `settings.agent.tools.tiering_enabled` (default `true`).
/// Quando attivo, il modello riceve solo il CORE di tool + discovery; gli altri
/// tool restano scopribili via `nexus_mcp_tool_search`.
async fn is_tiering_enabled(db: &PgPool) -> bool {
    let val: Option<String> = sqlx::query_scalar(
        "SELECT value FROM settings WHERE key = 'agent.tools.tiering_enabled'",
    )
    .fetch_optional(db)
    .await
    .ok()
    .flatten();
    match val {
        Some(s) => {
            let t = s.trim().to_ascii_lowercase();
            t == "true" || t == "1" || t == "yes"
        }
        // Default attivo: il tiering e' il comportamento voluto. Se la settings
        // manca (DB appena migrato senza il record), restiamo conservativi e
        // applichiamo comunque il tiering, che e' il default documentato.
        None => true,
    }
}

